    "label ²³⁵₉₂U below the initial uranium nucleus",
    "black arrow from uranium-235 to the unstable uranium-236 intermediate",
    "elongated pinched uranium-236 nucleus cluster made of green and off-white nucleon spheres",
    "red outline around the uranium-236 nucleus emphasizing instability",
    "label ²³⁶₉₂U below the intermediate nucleus",
    "text label 'Unstable nucleus' below uranium-236",
    "upper black arrow from uranium-236 to krypton-92",
    "lower black arrow from uranium-236 to barium-141",
    "smaller krypton-92 daughter nucleus cluster at upper right",
    "label ⁹²₃₆Kr beside the krypton nucleus",
    "larger barium-141 daughter nucleus cluster at lower right",
    "label ¹⁴¹₅₆Ba beside the barium nucleus",
    "gold starburst labeled 'Energy' between the daughter nuclei and emitted neutrons",
    "three emitted neutron spheres at far right",
    "three black arrows showing emitted neutrons moving outward from the fission event",
    "label 3 ¹₀n beside the emitted neutrons",
    "balanced nuclear equation along the bottom: ²³⁵₉₂U + ¹₀n → ²³⁶₉₂U → ¹⁴¹₅₆Ba + ⁹²₃₆Kr + 3 ¹₀n",
    "click-to-inspect information card for selected products showing nuclear symbol, mass number, atomic number, and chain-reaction role",
    "chain reaction inset or overlay showing one fission event branching into three emitted neutrons",
    "additional generation nodes in the chain reaction overlay representing secondary fissions triggered by emitted neutrons",
    "branching arrows in the chain reaction overlay showing neutrons from one fission triggering later fissions"
  ],
  "interactions": [
    {
      "id": "fissionSequence",
      "type": "animation",
      "label": "Play fission sequence",
      "loop": false,
