  while (pts.length < count && tries < count * 60) {
    tries++;
    var x = (rand() * 2 - 1) * rx;
    var y = (rand() * 2 - 1) * ry;
    var pinch = 1;
    if (ry > rx * 1.35) pinch = 0.62 + 0.38 * Math.min(1, Math.abs(y) / ry * 1.25);
    if ((x * x) / ((rx * pinch) * (rx * pinch)) + (y * y) / (ry * ry) <= 1) {
      pts.push({ x: cx + x, y: cy + y, p: rand() > 0.48 });
    }
