function lcg(seed) {
  var s = seed >>> 0;
  return function () {
    s = (1664525 * s + 1013904223) >>> 0;
    return s / 4294967296;
  };
}

function cluster(group, cx, cy, rx, ry, count, r, seed) {
  var rand = lcg(seed);
  var pts = [];
  var tries = 0;
  while (pts.length < count && tries < count * 90) {
    tries++;
    var x = (rand() * 2 - 1) * rx;
    var y = (rand() * 2 - 1) * ry;
    var pinch = 1;
    if (ry > rx * 1.32) {
      pinch = 0.52 + 0.48 * Math.min(1, Math.abs(y) / ry * 1.12);
    }
    if ((x * x) / ((rx * pinch) * (rx * pinch)) + (y * y) / (ry * ry) <= 1) {
      pts.push({ x: cx + x, y: cy + y, p: rand() > 0.47, rr: r * (0.86 + rand() * 0.25) });
    }
  }
  pts.sort(function (a, b) { return a.y - b.y; });
  for (var i = 0; i < pts.length; i++) {
    makeSphere(group, pts[i].x, pts[i].y, pts[i].rr, pts[i].p ? gradGreen : gradPale, pts[i].p ? 'p' : 'n');
  }
}

