sequenceGroups.products.add(isotopeLabel(1002, 377, 141, 56, 'Ba', 27));

sequenceGroups.energy = draw.group();
sequenceGroups.energy.add(makeBurst(895, 225, 48, 112, 10));
sequenceGroups.energy.text('Energy')
  .font({ family: 'Arial, sans-serif', size: 28, anchor: 'middle' })
  .center(895, 224)
  .attr({ 'paint-order': 'stroke', stroke: '#fff3c8', 'stroke-width': 3, 'stroke-linejoin': 'round' });

sequenceGroups.emitted = draw.group();
sequenceGroups.emitted.add(arrow(958, 180, 1028, 162, 3));
sequenceGroups.emitted.add(arrow(958, 222, 1028, 222, 3));
sequenceGroups.emitted.add(arrow(958, 258, 1028, 282, 3));
makeSphere(sequenceGroups.emitted, 1058, 155, 18, gradNeutron, 'n');
makeSphere(sequenceGroups.emitted, 1058, 222, 18, gradNeutron, 'n');
makeSphere(sequenceGroups.emitted, 1058, 290, 18, gradNeutron, 'n');
sequenceGroups.emitted.text('3 ¹₀n')
  .font({ family: 'Arial, sans-serif', size: 25, anchor: 'start' })
  .move(1088, 207)
  .attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3, 'stroke-linejoin': 'round' });

var eq = draw.text('²³⁵₉₂U + ¹₀n  ⟶  ²³⁶₉₂U  ⟶  ¹⁴¹₅₆Ba  +  ⁹²₃₆Kr  +  3 ¹₀n')
  .font({ family: 'Arial, sans-serif', size: 27, anchor: 'middle' })
  .center(560, 538)
  .attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3, 'stroke-linejoin': 'round' });

function addClickable(group, title, body, tip) {
  group.css('cursor', 'pointer');
  group.on('mousemove', function (e) { showTooltip(tip, e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () { showPopup(title, body); });
}

addClickable(sequenceGroups.incoming, 'Incoming neutron', 'Symbol: ¹₀n. Its mass number is 1 and atomic number is 0, so absorbing it adds one nucleon to uranium without adding a proton.', 'Click to inspect the incoming neutron');
addClickable(sequenceGroups.u235, 'Uranium-235', 'Symbol: ²³⁵₉₂U. Mass number 235 and atomic number 92 identify the fuel nucleus; after absorbing one neutron it becomes unstable uranium-236.', 'Click to inspect U-235');
addClickable(sequenceGroups.u236, 'Unstable uranium-236', 'Symbol: ²³⁶₉₂U. The absorbed neutron raises the mass number to 236 while the atomic number remains 92; the distorted nucleus quickly splits.', 'Click to inspect unstable U-236');
addClickable(krGroup, 'Krypton-92', 'Symbol: ⁹²₃₆Kr. Krypton-92 is one daughter fragment; its 36 protons combine with barium’s 56 to conserve uranium’s 92 protons.', 'Click to inspect Kr-92');
addClickable(baGroup, 'Barium-141', 'Symbol: ¹⁴¹₅₆Ba. Barium-141 is the larger daughter fragment; 141 + 92 + 3 emitted neutrons account for all 236 nucleons.', 'Click to inspect Ba-141');
addClickable(sequenceGroups.emitted, 'Released neutrons', 'Products: 3 ¹₀n. These three neutrons are the branching part of fission: if they strike other U-235 nuclei, they can start later fissions.', 'Click to inspect the three emitted neutrons');
addClickable(sequenceGroups.energy, 'Released energy', 'The gold burst represents energy released as the daughter nuclei and neutrons fly apart. It comes from the mass-energy difference between the initial and final products.', 'Click to inspect the energy release');
addClickable(eq, 'Balanced fission equation', 'Mass numbers balance: 235 + 1 = 236 and 141 + 92 + 3 = 236. Atomic numbers also balance: 92 + 0 = 56 + 36 + 0.', 'Click to check conservation in the equation');

var chainOverlay = draw.group();
chainOverlay.hide();

function smallFissionIcon(parent, x, y, scale) {
  var g = parent.group();
  g.circle(18 * scale).center(x - 5 * scale, y).fill('#6fa92d').stroke({ color: '#4a791d', width: 0.4 });
  g.circle(15 * scale).center(x + 7 * scale, y - 4 * scale).fill('#d8dac8').stroke({ color: '#999b84', width: 0.4 });
  g.circle(14 * scale).center(x + 5 * scale, y + 8 * scale).fill('#8ebb44').stroke({ color: '#4a791d', width: 0.4 });
  g.circle(6 * scale).center(x + 24 * scale, y - 1 * scale).fill(gradNeutron);
  return g;
}

function drawChainGeneration(gen) {
  chainOverlay.clear();
  if (gen <= 0) {
    chainOverlay.hide();
    return;
  }
  chainOverlay.show();
  chainOverlay.rect(470, 215).move(28, 302).rx(12).fill({ color: '#fff', opacity: 0.95 }).stroke({ color: '#777', width: 1.2 });
  chainOverlay.text('Chain reaction branching')
    .font({ family: 'Arial, sans-serif', size: 16, anchor: 'middle', weight: 'bold' })
    .center(263, 321);
  chainOverlay.text('generation ' + gen + ': up to ' + Math.pow(3, gen) + ' fission-triggering paths')
    .font({ family: 'Arial, sans-serif', size: 13, anchor: 'middle' })
    .center(263, 343);

  var x0 = 75;
  var xGap = 92;
  var nodes = [{ x: x0, y: 410, level: 0 }];
  for (var level = 0; level <= gen; level++) {
    var current = nodes.filter(function (n) { return n.level === level; });
    var maxDraw = level >= 4 ? 27 : current.length;
    for (var i = 0; i < Math.min(current.length, maxDraw); i++) {
      smallFissionIcon(chainOverlay, current[i].x, current[i].y, 1);
    }
    if (level === gen) break;
    var next = [];
    for (var j = 0; j < current.length && next.length < 27; j++) {
      var parent = current[j];
      var spread = 80 / Math.pow(1.45, level);
      for (var k = 0; k < 3; k++) {
        var dy = (k - 1) * spread + (j % 2 ? 7 : -7);
        var child = {
          x: x0 + (level + 1) * xGap,
          y: Math.max(365, Math.min(486, parent.y + dy)),
          level: level + 1
        };
        next.push(child);
        chainOverlay.line(parent.x + 24, parent.y, child.x - 24, child.y)
          .stroke({ color: '#111', width: 1.4, linecap: 'round' })
          .marker('end', arrowMarker);
        chainOverlay.circle(6).center((parent.x + child.x) / 2, (parent.y + child.y) / 2).fill(gradNeutron);
      }
    }
    nodes = nodes.concat(next);
  }
  if (gen === 4) {
    chainOverlay.text('many more branches…')
      .font({ family: 'Arial, sans-serif', size: 12, anchor: 'middle', style: 'italic' })
      .center(416, 490);
  }
  chainOverlay.front();
}

function update_chainGeneration(v) {
  var val = Math.max(0, Math.min(4, Math.round(v)));
  document.getElementById('chainGenerationInput').value = val;
  document.getElementById('chainGenerationVal').value = val;
  drawChainGeneration(val);
}

var animTimer = null;

function clearHalos() {
  phaseHalo.clear();
}

function highlightRect(x, y, w, h) {
  clearHalos();
  phaseHalo.rect(w, h).move(x, y).rx(18)
    .fill('none')
    .stroke({ color: '#f2c84b', width: 5, dasharray: '9 7', opacity: 0.95 });
  phaseHalo.front();
}

function setSequencePhase(phase) {
  var all = ['incoming', 'u235', 'toIntermediate', 'u236', 'splitArrows', 'products', 'energy', 'emitted'];
  for (var i = 0; i < all.length; i++) sequenceGroups[all[i]].opacity(0.2);
  eq.opacity(0.35);
  if (phase >= 0) {
    sequenceGroups.incoming.opacity(1);
    sequenceGroups.u235.opacity(1);
    highlightRect(0, 96, 410, 295);
  }
  if (phase >= 1) {
    sequenceGroups.toIntermediate.opacity(1);
    sequenceGroups.u236.opacity(1);
    highlightRect(505, 25, 180, 462);
  }
  if (phase >= 2) {
    sequenceGroups.splitArrows.opacity(1);
    sequenceGroups.products.opacity(1);
    highlightRect(790, 8, 235, 460);
  }
  if (phase >= 3) {
    sequenceGroups.energy.opacity(1);
    sequenceGroups.emitted.opacity(1);
    eq.opacity(1);
    highlightRect(770, 125, 345, 195);
  }
  if (phase >= 4) {
    for (var j = 0; j < all.length; j++) sequenceGroups[all[j]].opacity(1);
    eq.opacity(1);
    clearHalos();
  }
}

function restoreFullDiagram() {
  var all = ['incoming', 'u235', 'toIntermediate', 'u236', 'splitArrows', 'products', 'energy', 'emitted'];
  for (var i = 0; i < all.length; i++) sequenceGroups[all[i]].opacity(1);
  eq.opacity(1);
  clearHalos();
}

function trigger_fissionSequence() {
  if (animTimer) clearInterval(animTimer);
  update_chainGeneration(0);
  var phase = 0;
  setSequencePhase(0);
  animTimer = setInterval(function () {
    phase++;
    setSequencePhase(phase);
    if (phase >= 4) {
      clearInterval(animTimer);
      animTimer = null;
      setTimeout(restoreFullDiagram, 650);
    }
  }, 1050);
}

var demoSteps = [
  {
    title: 'Start with neutron capture',
    narration: 'A slow neutron approaches U-235 and is absorbed by the nucleus. This increases the mass number from 235 to 236 while the atomic number remains 92.',
    state: { chainGeneration: 0 }
  },
  {
    title: 'Form the unstable intermediate',
    narration: 'The captured neutron produces U-236, shown as elongated and pinched with a red outline. The distorted shape emphasizes that this intermediate is short-lived and unstable.',
    state: { chainGeneration: 0 }
  },
  {
    title: 'Split into products',
    narration: 'The unstable nucleus splits into Ba-141 and Kr-92, releases a burst of energy, and ejects three neutrons. Click each product to read its mass number, atomic number, and role.',
    state: { chainGeneration: 0 }
  },
  {
    title: 'Check conservation in the equation',
    narration: 'The equation at the bottom balances both mass number and atomic number: 235 + 1 = 236, and the final products also total 236 nucleons and 92 protons.',
    state: { chainGeneration: 0 }
  },
  {
    title: 'Grow a chain reaction',
    narration: 'Move the chain reaction slider to let the three emitted neutrons trigger new U-235 fissions. Each successful generation branches into more events, showing why fission can become self-sustaining.',
    state: { chainGeneration: 3 }
  }
];

var currentStep = 0;

function applyStep(i) {
  if (animTimer) {
    clearInterval(animTimer);
    animTimer = null;
  }
  currentStep = Math.max(0, Math.min(demoSteps.length - 1, i));
  var step = demoSteps[currentStep];
  document.getElementById('demoNarration').textContent = step.narration;
  document.getElementById('stepLabel').textContent = (currentStep + 1) + '/' + demoSteps.length;
  if (step.state && step.state.chainGeneration != null) update_chainGeneration(step.state.chainGeneration);
  restoreFullDiagram();
  if (currentStep === 1) highlightRect(505, 25, 180, 462);
  if (currentStep === 2) highlightRect(770, 8, 345, 460);
  if (currentStep === 3) highlightRect(178, 506, 760, 45);
  if (currentStep === 4) {
    clearHalos();
    chainOverlay.front();
  }
}

function prevStep() {
  applyStep(currentStep - 1);
}

function nextStep() {
  applyStep(currentStep + 1);
}

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: Neutron-induced fission occurs when U-235 absorbs a neutron to form unstable U-236, which splits into smaller nuclei while releasing energy and multiple neutrons capable of sustaining a chain reaction.
KEY INSIGHT (what students should walk away understanding): One absorbed neutron can release three new neutrons, so fission is not just a splitting event but a branching process capable of sustaining a chain reaction.
DEMO STEPS: 5 guided steps — implement the step player in #ui

FULL BLUEPRINT:
