function lcg(seed) {
  var s = seed >>> 0;
  return function () {
    s = (1664525 * s + 1013904223) >>> 0;
    return s / 4294967296;
  };
}

function cluster(group, cx, cy, rx, ry, count, r, seed, pinchMode) {
  var rand = lcg(seed);
  var pts = [];
  var grid = Math.ceil(Math.sqrt(count * 1.42));
  for (var gy = -grid; gy <= grid; gy++) {
    for (var gx = -grid; gx <= grid; gx++) {
      var nx = gx / grid;
      var ny = gy / grid;
      var pinch = 1;
      if (pinchMode) pinch = 0.45 + 0.55 * Math.min(1, Math.abs(ny) * 1.3);
      if ((nx * nx) / (pinch * pinch) + ny * ny <= 1.02 && rand() > 0.08) {
        pts.push({
          x: cx + nx * rx + (rand() - 0.5) * r * 1.25,
          y: cy + ny * ry + (rand() - 0.5) * r * 1.25,
          p: rand() > 0.47,
          rr: r * (0.86 + rand() * 0.26)
        });
      }
    }
  }
  while (pts.length < count) {
    var x = (rand() * 2 - 1) * rx;
    var y = (rand() * 2 - 1) * ry;
    var ny2 = y / ry;
    var pinch2 = pinchMode ? 0.45 + 0.55 * Math.min(1, Math.abs(ny2) * 1.3) : 1;
    if ((x * x) / ((rx * pinch2) * (rx * pinch2)) + (y * y) / (ry * ry) <= 1) {
      pts.push({ x: cx + x, y: cy + y, p: rand() > 0.47, rr: r * (0.86 + rand() * 0.26) });
    }
  }
  pts = pts.slice(0, count);
  pts.sort(function (a, b) { return a.y - b.y; });
  for (var i = 0; i < pts.length; i++) {
    makeSphere(group, pts[i].x, pts[i].y, pts[i].rr, pts[i].p ? gradGreen : gradPale, pts[i].p ? 'p' : 'n');
  }
}

function makeBurst(parent, cx, cy, r1, r2, spikes) {
  var pts = [];
  for (var i = 0; i < spikes * 2; i++) {
    var a = -Math.PI / 2 + i * Math.PI / spikes;
    var r = i % 2 ? r1 : r2;
    pts.push([cx + Math.cos(a) * r, cy + Math.sin(a) * r]);
  }
  return parent.polygon(pts.map(function (p) { return p[0] + ',' + p[1]; }).join(' '))
    .fill({ color: '#f0d26d', opacity: 0.55 })
    .stroke('none');
}

