addClickable(eq, 'Balanced fission equation', 'Mass numbers balance: 235 + 1 = 236 and 141 + 92 + 3 = 236. Atomic numbers also balance: 92 + 0 = 56 + 36 + 0.', 'Click to check conservation in the equation');

var chainOverlay = draw.group();
chainOverlay.hide();

function smallFissionIcon(parent, x, y, scale) {
  var g = parent.group();
  g.circle(18 * scale).center(x - 6 * scale, y).fill(gradGreen).stroke({ color: '#4a791d', width: 0.5 });
  g.circle(16 * scale).center(x + 8 * scale, y - 5 * scale).fill(gradPale).stroke({ color: '#999b84', width: 0.5 });
  g.circle(15 * scale).center(x + 5 * scale, y + 9 * scale).fill(gradGreen).stroke({ color: '#4a791d', width: 0.5 });
  g.circle(7 * scale).center(x + 27 * scale, y - 1 * scale).fill(gradNeutron).stroke({ color: '#999b84', width: 0.3 });
  return g;
}

function drawChainGeneration(gen) {
  chainOverlay.clear();
  if (gen <= 0) {
    chainOverlay.hide();
    return;
  }
  chainOverlay.show();
  chainOverlay.rect(498, 210).move(28, 315).rx(12)
    .fill({ color: '#fff', opacity: 0.96 })
    .stroke({ color: '#777', width: 1.2 });
  addText(chainOverlay, 'Chain reaction branching', 277, 336, 17, 'middle', 'bold');
  addText(chainOverlay, 'generation ' + gen + ': up to ' + Math.pow(3, gen) + ' fission-triggering paths', 277, 358, 13, 'middle');

  var x0 = 75;
  var xGap = 96;
  var nodes = [{ x: x0, y: 424, level: 0 }];
  for (var level = 0; level <= gen; level++) {
    var current = nodes.filter(function (n) { return n.level === level; });
    var maxDraw = level >= 4 ? 27 : current.length;
    for (var i = 0; i < Math.min(current.length, maxDraw); i++) {
      smallFissionIcon(chainOverlay, current[i].x, current[i].y, 1);
    }
    if (level === gen) break;
    var next = [];
    for (var j = 0; j < current.length && next.length < 27; j++) {
      var p = current[j];
      var spread = 80 / Math.pow(1.45, level);
      for (var k = 0; k < 3; k++) {
        var dy = (k - 1) * spread + (j % 2 ? 7 : -7);
        var child = {
          x: x0 + (level + 1) * xGap,
          y: Math.max(375, Math.min(505, p.y + dy)),
          level: level + 1
        };
        next.push(child);
        chainOverlay.line(p.x + 25, p.y, child.x - 25, child.y)
          .stroke({ color: '#111', width: 1.35, linecap: 'round' })
          .marker('end', arrowMarker);
        chainOverlay.circle(6).center((p.x + child.x) / 2, (p.y + child.y) / 2).fill(gradNeutron);
      }
    }
    nodes = nodes.concat(next);
  }
  if (gen === 4) {
    addText(chainOverlay, 'many more branches…', 432, 510, 12, 'middle');
  }
  chainOverlay.front();
}

function update_chainGeneration(v) {
  var val = Math.max(0, Math.min(4, Math.round(v)));
  document.getElementById('chainGenerationInput').value = val;
  document.getElementById('chainGenerationVal').value = val;
  drawChainGeneration(val);
}

var animTimer = null;

function clearHalos() {
  phaseHalo.clear();
}

function highlightRect(x, y, w, h) {
  clearHalos();
  phaseHalo.rect(w, h).move(x, y).rx(18)
    .fill('none')
    .stroke({ color: '#f2c84b', width: 5, dasharray: '9 7', opacity: 0.95 });
  phaseHalo.front();
}

function setSequencePhase(phase) {
  var all = ['incoming', 'u235', 'toIntermediate', 'u236', 'splitArrows', 'products', 'energy', 'emitted'];
  for (var i = 0; i < all.length; i++) sequenceGroups[all[i]].opacity(0.18);
  eq.opacity(0.32);
  clearHalos();
  if (phase >= 0) {
    sequenceGroups.incoming.opacity(1);
    sequenceGroups.u235.opacity(1);
    highlightRect(0, 96, 410, 305);
  }
  if (phase >= 1) {
    sequenceGroups.toIntermediate.opacity(1);
    sequenceGroups.u236.opacity(1);
    highlightRect(505, 25, 185, 472);
  }
  if (phase >= 2) {
    sequenceGroups.splitArrows.opacity(1);
    sequenceGroups.products.opacity(1);
    highlightRect(785, 5, 238, 465);
  }
  if (phase >= 3) {
    sequenceGroups.energy.opacity(1);
    sequenceGroups.emitted.opacity(1);
    eq.opacity(1);
    highlightRect(770, 125, 360, 205);
  }
  if (phase >= 4) {
    for (var j = 0; j < all.length; j++) sequenceGroups[all[j]].opacity(1);
    eq.opacity(1);
    clearHalos();
  }
}

function restoreFullDiagram() {
  var all = ['incoming', 'u235', 'toIntermediate', 'u236', 'splitArrows', 'products', 'energy', 'emitted'];
  for (var i = 0; i < all.length; i++) sequenceGroups[all[i]].opacity(1);
  eq.opacity(1);
  clearHalos();
}

function trigger_fissionSequence() {
  if (animTimer) clearInterval(animTimer);
  update_chainGeneration(0);
  var phase = 0;
  setSequencePhase(0);
  animTimer = setInterval(function () {
    phase++;
    setSequencePhase(phase);
    if (phase >= 4) {
      clearInterval(animTimer);
      animTimer = null;
      setTimeout(restoreFullDiagram, 650);
    }
  }, 1050);
}

var demoSteps = [
  {
    title: 'Start with neutron capture',
    narration: 'A slow neutron approaches U-235 and is absorbed by the nucleus. This increases the mass number from 235 to 236 while the atomic number remains 92.',
    state: { chainGeneration: 0 }
  },
  {
    title: 'Form the unstable intermediate',
    narration: 'The captured neutron produces U-236, shown as elongated and pinched with a red outline. The distorted shape emphasizes that this intermediate is short-lived and unstable.',
    state: { chainGeneration: 0 }
  },
  {
    title: 'Split into products',
    narration: 'The unstable nucleus splits into Ba-141 and Kr-92, releases a burst of energy, and ejects three neutrons. Click each product to read its mass number, atomic number, and role.',
    state: { chainGeneration: 0 }
  },
  {
    title: 'Check conservation in the equation',
    narration: 'The equation at the bottom balances both mass number and atomic number: 235 + 1 = 236, and the final products also total 236 nucleons and 92 protons.',
    state: { chainGeneration: 0 }
  },
  {
    title: 'Grow a chain reaction',
    narration: 'Move the chain reaction slider to let the three emitted neutrons trigger new U-235 fissions. Each successful generation branches into more events, showing why fission can become self-sustaining.',
    state: { chainGeneration: 3 }
  }
];

var currentStep = 0;

function applyStep(i) {
  if (animTimer) {
    clearInterval(animTimer);
    animTimer = null;
  }
  currentStep = Math.max(0, Math.min(demoSteps.length - 1, i));
  var step = demoSteps[currentStep];
  document.getElementById('demoNarration').textContent = step.narration;
  document.getElementById('stepLabel').textContent = (currentStep + 1) + '/' + demoSteps.length;
  if (step.state && step.state.chainGeneration != null) update_chainGeneration(step.state.chainGeneration);
  restoreFullDiagram();
  if (currentStep === 1) highlightRect(505, 25, 185, 472);
  if (currentStep === 2) highlightRect(770, 5, 360, 465);
  if (currentStep === 3) highlightRect(175, 515, 765, 50);
  if (currentStep === 4) {
    clearHalos();
    chainOverlay.front();
  }
}

function prevStep() {
  applyStep(currentStep - 1);
}

function nextStep() {
  applyStep(currentStep + 1);
}

applyStep(0);
window.__markRendered();
